import { extendAsamI18n } from '@asam-ui/ui/i18n';
import type { AsamI18n } from '@asam-ui/ui/i18n';
import { createAsamMessageIssue, formatFieldIssue } from '@asam-ui/pro/i18n';
import { chatMessageDefaults } from './I18n.js';
import { computed, shallowReadonly, shallowRef } from 'vue';
import { chatKey, decodeMessages, decodeSessions, isTool } from './Protocol.js';
import type {
	ChatEvent,
	ChatId,
	ChatMessage,
	ChatOptions,
	ChatPhase,
	ChatReadContext,
	ChatResponse,
	ChatSnapshot
} from './Types.js';

type MessageIssue = ReturnType<typeof createAsamMessageIssue>;
type ErrorField = 'listError' | 'historyError' | 'responseError';
interface Attempt {
	id: string;
	userId: string;
	assistant: ChatMessage;
	tools: Map<string, ChatMessage>;
	sessionKey: string;
	controller: AbortController;
	generation: number;
	sequence: number;
	started: boolean;
	sealed: boolean;
	timer?: ReturnType<typeof setTimeout>;
}
interface Conversation {
	messages: readonly ChatMessage[];
	draft: string;
	phase: ChatPhase;
	error: string;
	errorSource?: MessageIssue;
	loaded: boolean;
	retryUser?: string;
}
let instanceSequence = 0;

/** Owns only view operations. Never disposes the borrowed service, reader or request client. */
export function createChatController(initial: ChatOptions, owner?: AsamI18n) {
	const i18n = owner ? extendAsamI18n(owner, chatMessageDefaults) : undefined;
	const sources = new WeakMap<ChatSnapshot, Partial<Record<ErrorField, MessageIssue>>>();
	let options = { ...initial };
	let generation = 0;
	let action = 0;
	let listVersion = 0;
	let historyVersion = 0;
	let disposed = false;
	let transitioning = false;
	let active: Attempt | undefined;
	let listAbort: AbortController | undefined;
	let historyAbort: AbortController | undefined;
	const namespace = `chat-${++instanceSequence}`;
	let sequence = 0;
	// Historical IDs are opaque and may contain any of our previous generated formats.
	// Reserve every accepted history and locally allocated identity, across scope/reset as well.
	const reservedIdentities = new Set<string>();
	function identity(kind: 'user' | 'attempt' | 'assistant' | 'tool'): string {
		let id: string;
		do id = `${namespace}:${kind}:${++sequence}`;
		while (reservedIdentities.has(id));
		reservedIdentities.add(id);
		return id;
	}
	function replaceOwned(row: Conversation, previous: ChatMessage, next: ChatMessage) {
		row.messages = Object.freeze(
			row.messages.map((message) => (message === previous ? next : message))
		);
	}
	const conversations = new Map<string, Conversation>();
	const state = shallowRef<ChatSnapshot>({
		scope: options.scope ?? '',
		generation,
		sessions: [],
		selected: null,
		messages: [],
		draft: '',
		listPhase: 'idle',
		historyPhase: 'idle',
		listError: '',
		historyError: '',
		responseError: '',
		phase: 'idle',
		readonly: !!options.readonly,
		disabled: !!options.disabled,
		canSend: false,
		canRetry: false,
		discardedEvents: 0
	});
	const selectedKey = () =>
		state.value.selected === null ? undefined : chatKey(state.value.selected);
	const conversation = () => {
		const key = selectedKey();
		return key === undefined ? undefined : conversations.get(key);
	};
	function publish(
		patch: Partial<ChatSnapshot> = {},
		owned: Partial<Record<ErrorField, MessageIssue | undefined>> = {}
	) {
		if (disposed) return;
		const issueSources = { ...sources.get(state.value), ...owned };
		for (const key of ['listError', 'historyError', 'responseError'] as const)
			if (patch[key] === '') delete issueSources[key];
		const next = { ...state.value, ...patch };
		const row =
			next.selected === null
				? undefined
				: next.sessions.find((s) => chatKey(s.id) === chatKey(next.selected!));
		const record =
			next.selected === null ? undefined : conversations.get(chatKey(next.selected));
		const permitted =
			!!row &&
			row.canSend !== false &&
			!options.readonly &&
			!options.disabled &&
			next.listPhase !== 'loading' &&
			next.historyPhase === 'ready' &&
			record?.loaded === true &&
			next.phase !== 'responding';
		const snapshot = Object.freeze({
			...next,
			readonly: !!options.readonly,
			disabled: !!options.disabled,
			canSend: permitted,
			canRetry: permitted && !!record?.retryUser
		});
		// Bind before publishing so synchronous readers see this snapshot's own source.
		sources.set(snapshot, issueSources);
		state.value = snapshot;
	}
	function render() {
		const row = conversation();
		publish(
			{
				messages: row?.messages ?? [],
				draft: row?.draft ?? '',
				phase: row?.phase ?? 'idle',
				responseError: row?.error ?? ''
			},
			{ responseError: row?.errorSource }
		);
	}
	function current(attempt: Attempt) {
		return (
			!disposed &&
			active === attempt &&
			attempt.generation === generation &&
			selectedKey() === attempt.sessionKey
		);
	}
	function settle(
		attempt: Attempt,
		phase: 'completed' | 'stopped' | 'error',
		error: string | MessageIssue = ''
	) {
		if (!current(attempt) || attempt.sealed) return;
		attempt.sealed = true;
		clearTimeout(attempt.timer);
		const row = conversations.get(attempt.sessionKey)!;
		const next = Object.freeze({ ...attempt.assistant, phase });
		replaceOwned(row, attempt.assistant, next);
		attempt.assistant = next;
		row.phase = phase;
		row.error = typeof error === 'string' ? error : error.message;
		row.errorSource = typeof error === 'string' ? undefined : error;
		row.retryUser = phase === 'completed' ? undefined : attempt.userId;
		// Seal before publication or abort: synchronous observers/host callbacks may reenter.
		render();
		attempt.controller.abort();
	}
	function stop() {
		if (active && !active.sealed)
			settle(
				active,
				'stopped',
				createAsamMessageIssue(
					'回答已停止，已收到的内容保留。可显式重试。',
					'app.templates.chat.stoppedError'
				)
			);
	}
	function cancelReads() {
		++listVersion;
		++historyVersion;
		const list = listAbort,
			history = historyAbort;
		listAbort = undefined;
		historyAbort = undefined;
		publish({
			listPhase: state.value.listPhase === 'loading' ? 'idle' : state.value.listPhase,
			historyPhase: state.value.historyPhase === 'loading' ? 'idle' : state.value.historyPhase
		});
		list?.abort();
		history?.abort();
	}
	function context(signal: AbortSignal): ChatReadContext {
		return { scope: options.scope ?? '', generation, signal };
	}
	async function reload() {
		if (disposed || transitioning || options.disabled) return false;
		const version = ++listVersion,
			epoch = generation,
			service = options.service;
		const old = listAbort;
		const abort = new AbortController();
		listAbort = abort;
		old?.abort();
		const valid = () =>
			!disposed && epoch === generation && version === listVersion && !abort.signal.aborted;
		if (!valid()) return false;
		publish({ listPhase: 'loading', listError: '' });
		if (!valid()) return false;
		try {
			const sessions = decodeSessions(await service.list(context(abort.signal)));
			if (!valid()) return false;
			const selected = state.value.selected;
			const retained =
				selected === null
					? undefined
					: sessions.find((s) => chatKey(s.id) === chatKey(selected));
			if (!retained || retained.canSend === false) stop();
			if (!valid()) return false;
			const selectionAction = action;
			publish({ sessions, listPhase: 'ready' });
			if (!valid()) return false;
			if (!retained && selectionAction === action) {
				if (sessions[0]) return await select(sessions[0].id);
				await select(null);
			}
			return true;
		} catch {
			if (valid())
				publish(
					{
						listPhase: 'error',
						listError: '会话列表读取失败，保留上一版本。请重试。'
					},
					{
						listError: createAsamMessageIssue(
							'会话列表读取失败，保留上一版本。请重试。',
							'app.templates.chat.listError'
						)
					}
				);
			return false;
		} finally {
			if (listAbort === abort) listAbort = undefined;
		}
	}
	async function select(id: ChatId | null, force = false) {
		if (disposed || transitioning || options.disabled) return false;
		if (!force && id !== null && selectedKey() === chatKey(id) && conversation()?.loaded)
			return true;
		const operation = ++action;
		const key = id === null ? undefined : chatKey(id);
		stop();
		if (disposed || operation !== action) return false;
		active = undefined;
		const version = ++historyVersion,
			epoch = generation,
			service = options.service;
		const old = historyAbort;
		const abort = new AbortController();
		historyAbort = abort;
		old?.abort();
		const valid = () =>
			!disposed &&
			epoch === generation &&
			operation === action &&
			version === historyVersion &&
			!abort.signal.aborted;
		if (!valid()) return false;
		if (key === undefined) {
			publish({ selected: null, historyPhase: 'idle', historyError: '' });
			render();
			return true;
		}
		if (!state.value.sessions.some((s) => chatKey(s.id) === key)) {
			publish(
				{
					selected: id,
					messages: [],
					draft: '',
					phase: 'idle',
					responseError: '',
					historyPhase: 'error',
					historyError: '会话不存在或已无访问权限，请选择其他会话。'
				},
				{
					historyError: createAsamMessageIssue(
						'会话不存在或已无访问权限，请选择其他会话。',
						'app.templates.chat.missingSession'
					)
				}
			);
			return false;
		}
		if (!conversations.has(key))
			conversations.set(key, {
				messages: [],
				draft: '',
				phase: 'idle',
				error: '',
				loaded: false
			});
		const row = conversations.get(key)!;
		publish(
			{
				selected: id,
				messages: row.messages,
				draft: row.draft,
				phase: row.phase,
				responseError: row.error,
				historyError: '',
				historyPhase: row.loaded && !force ? 'ready' : 'loading'
			},
			{ responseError: row.errorSource }
		);
		if (!valid()) return false;
		if (row.loaded && !force) return true;
		try {
			const messages = decodeMessages(await service.history(id!, context(abort.signal)));
			if (!valid()) return false;
			for (const message of messages) {
				reservedIdentities.add(message.id);
				if (message.tool) reservedIdentities.add(message.tool.id);
			}
			row.messages = messages;
			row.loaded = true;
			row.phase = 'idle';
			row.error = '';
			row.errorSource = undefined;
			row.retryUser = undefined;
			publish({ historyPhase: 'ready' });
			if (valid()) render();
			return true;
		} catch {
			if (valid())
				publish(
					{
						historyPhase: 'error',
						historyError: '历史记录读取失败，可重试。已有记录保留。'
					},
					{
						historyError: createAsamMessageIssue(
							'历史记录读取失败，可重试。已有记录保留。',
							'app.templates.chat.historyError'
						)
					}
				);
			return false;
		} finally {
			if (historyAbort === abort) historyAbort = undefined;
		}
	}
	function accept(attempt: Attempt, event: ChatEvent) {
		if (!current(attempt)) return;
		if (attempt.sealed) {
			publish({ discardedEvents: state.value.discardedEvents + 1 });
			return;
		}
		const invalid = () =>
			settle(
				attempt,
				'error',
				createAsamMessageIssue(
					'响应事件格式或顺序无效，已保留部分内容。请显式重试。',
					'app.templates.chat.invalidEvent'
				)
			);
		if (
			!event ||
			typeof event !== 'object' ||
			event.attemptId !== attempt.id ||
			!Number.isSafeInteger(event.sequence) ||
			event.sequence !== attempt.sequence + 1
		) {
			invalid();
			return;
		}
		if (!attempt.started && event.type !== 'start') {
			invalid();
			return;
		}
		attempt.sequence = event.sequence;
		const row = conversations.get(attempt.sessionKey)!;
		switch (event.type) {
			case 'start':
				if (attempt.started) {
					invalid();
					return;
				}
				attempt.started = true;
				break;
			case 'text-delta':
				if (typeof event.text !== 'string') {
					invalid();
					return;
				}
				{
					const next = Object.freeze({
						...attempt.assistant,
						text: attempt.assistant.text + event.text
					});
					replaceOwned(row, attempt.assistant, next);
					attempt.assistant = next;
				}
				break;
			case 'tool-state': {
				if (!isTool(event.tool)) {
					invalid();
					return;
				}
				const previous = attempt.tools.get(event.tool.id);
				const id = previous?.id ?? identity('tool');
				const tool: ChatMessage = Object.freeze({
					id,
					role: 'tool',
					text: event.tool.text,
					tool: Object.freeze({ ...event.tool }),
					attemptId: attempt.id,
					replyTo: attempt.userId
				});
				attempt.tools.set(event.tool.id, tool);
				if (previous) replaceOwned(row, previous, tool);
				else row.messages = Object.freeze([...row.messages, tool]);
				break;
			}
			case 'complete':
				settle(attempt, 'completed');
				return;
			case 'error':
				if (!['unavailable', 'denied'].includes(event.code)) {
					invalid();
					return;
				}
				settle(
					attempt,
					'error',
					event.code === 'denied'
						? createAsamMessageIssue(
								'当前无权继续回答。部分内容已保留。',
								'app.templates.chat.deniedError'
							)
						: createAsamMessageIssue(
								'回答服务暂时不可用。部分内容已保留，可显式重试。',
								'app.templates.chat.unavailableError'
							)
				);
				return;
			default:
				invalid();
				return;
		}
		render();
	}
	async function begin(retry: boolean) {
		if (disposed || transitioning || !(retry ? state.value.canRetry : state.value.canSend))
			return false;
		const row = conversation()!;
		const existing = retry
			? row.messages.find((m) => m.id === row.retryUser && m.role === 'user')
			: undefined;
		const text = retry ? existing?.text : row.draft;
		if (!text?.trim()) return false;
		const userId = existing?.id ?? identity('user');
		const id = identity('attempt');
		const assistant: ChatMessage = Object.freeze({
			id: identity('assistant'),
			role: 'assistant',
			text: '',
			attemptId: id,
			replyTo: userId,
			phase: 'responding'
		});
		const attempt: Attempt = {
			id,
			userId,
			assistant,
			tools: new Map(),
			sessionKey: selectedKey()!,
			controller: new AbortController(),
			generation,
			sequence: 0,
			started: false,
			sealed: false
		};
		active = attempt;
		const service = options.service;
		const request = Object.freeze({
			scope: options.scope ?? '',
			generation,
			sessionId: state.value.selected!,
			userId,
			attemptId: id,
			text
		});
		const user: ChatMessage = Object.freeze({ id: userId, role: 'user', text });
		row.messages = Object.freeze([...row.messages, ...(retry ? [] : [user]), assistant]);
		row.draft = retry ? row.draft : '';
		row.phase = 'responding';
		row.error = '';
		row.errorSource = undefined;
		row.retryUser = undefined;
		const timeout = options.responseTimeoutMs ?? 15000;
		attempt.timer = setTimeout(
			() =>
				settle(
					attempt,
					'error',
					createAsamMessageIssue(
						'回答超时，部分内容已保留。请显式重试。',
						'app.templates.chat.timeoutError'
					)
				),
			timeout
		);
		render();
		if (!current(attempt) || attempt.sealed) return false;
		try {
			const result: ChatResponse = await service.respond(request, {
				signal: attempt.controller.signal,
				emit: (event) => accept(attempt, event)
			});
			if (!current(attempt) || attempt.sealed) return true;
			if (
				result?.mode === 'complete' &&
				!attempt.started &&
				typeof result.text === 'string' &&
				(result.tools === undefined ||
					(Array.isArray(result.tools) && result.tools.every(isTool)))
			) {
				accept(attempt, { type: 'start', attemptId: id, sequence: 1 });
				accept(attempt, {
					type: 'text-delta',
					attemptId: id,
					sequence: 2,
					text: result.text
				});
				for (const tool of result.tools ?? [])
					accept(attempt, {
						type: 'tool-state',
						attemptId: id,
						sequence: attempt.sequence + 1,
						tool
					});
				accept(attempt, {
					type: 'complete',
					attemptId: id,
					sequence: attempt.sequence + 1
				});
			} else
				settle(
					attempt,
					'error',
					createAsamMessageIssue(
						'响应结束但未收到完整终态，部分内容已保留。请显式重试。',
						'app.templates.chat.terminalError'
					)
				);
			return true;
		} catch {
			settle(
				attempt,
				'error',
				createAsamMessageIssue(
					'回答服务暂时不可用。部分内容已保留，可显式重试。',
					'app.templates.chat.unavailableError'
				)
			);
			return false;
		}
	}
	function configure(next: ChatOptions) {
		if (disposed) return;
		const timeout = next.responseTimeoutMs ?? 15000;
		if (!Number.isFinite(timeout) || timeout < 1 || timeout > 2147483647)
			throw new TypeError('Invalid responseTimeoutMs');
		const replaced =
			next.service !== options.service || (next.scope ?? '') !== (options.scope ?? '');
		options = { ...next };
		if (replaced) {
			clear();
			return;
		}
		if (options.readonly || options.disabled) stop();
		if (options.disabled) cancelReads();
		publish();
	}
	function clear(final = false) {
		if (disposed || transitioning) return;
		transitioning = true;
		++generation;
		++action;
		const old = active;
		const oldList = listAbort,
			oldHistory = historyAbort;
		active = undefined;
		listAbort = undefined;
		historyAbort = undefined;
		++listVersion;
		++historyVersion;
		clearTimeout(old?.timer);
		conversations.clear();
		publish({
			scope: options.scope ?? '',
			generation,
			sessions: [],
			selected: null,
			messages: [],
			draft: '',
			phase: 'idle',
			responseError: '',
			listError: '',
			historyError: '',
			listPhase: 'idle',
			historyPhase: 'idle',
			discardedEvents: 0
		});
		transitioning = false;
		if (final) disposed = true;
		oldList?.abort();
		oldHistory?.abort();
		old?.controller.abort();
	}
	configure(initial);
	return {
		state: shallowReadonly(state),
		formatError(snapshot: ChatSnapshot, field: ErrorField) {
			const issue = sources.get(snapshot)?.[field];
			return i18n && issue ? formatFieldIssue(issue, i18n) : snapshot[field];
		},
		busy: computed(() => state.value.phase === 'responding'),
		reload,
		select,
		retryHistory: () =>
			state.value.selected === null
				? Promise.resolve(false)
				: select(state.value.selected, true),
		setDraft(text: string) {
			const row = conversation();
			if (!disposed && row && !options.readonly && !options.disabled) {
				row.draft = text;
				render();
			}
		},
		send: () => begin(false),
		retry: () => begin(true),
		stop,
		cancelReads,
		configure,
		reset: () => clear(),
		dispose() {
			if (disposed) return;
			clear(true);
			i18n?.dispose();
		}
	};
}
export type ChatController = ReturnType<typeof createChatController>;

import { useAsamProI18n } from '@asam-ui/pro/i18n';
import { chatMessagesEn } from './I18nEn.js';
import { chatMessagesZh } from './I18nZh.js';
export const chatMessageDefaults = Object.freeze({ en: chatMessagesEn, 'zh-CN': chatMessagesZh });
export function useChatI18n() {
	return useAsamProI18n(chatMessageDefaults);
}

export interface ChatMessageParameters {
	'app.templates.chat.readonly': Record<never, never>;
	'app.templates.chat.disabled': Record<never, never>;
	'app.templates.chat.message': Record<never, never>;
	'app.templates.chat.placeholder': Record<never, never>;
	'app.templates.chat.keyboard': Record<never, never>;
	'app.templates.chat.stop': Record<never, never>;
	'app.templates.chat.retry': Record<never, never>;
	'app.templates.chat.send': Record<never, never>;
	'app.templates.chat.ready': Record<never, never>;
	'app.templates.chat.respondingHint': Record<never, never>;
	'app.templates.chat.completedHint': Record<never, never>;
	'app.templates.chat.stoppedHint': Record<never, never>;
	'app.templates.chat.errorHint': Record<never, never>;
	'app.templates.chat.sessions': Record<never, never>;
	'app.templates.chat.sessionsTitle': Record<never, never>;
	'app.templates.chat.sessionsLoading': Record<never, never>;
	'app.templates.chat.sessionsEmpty': Record<never, never>;
	'app.templates.chat.readonlySession': Record<never, never>;
	'app.templates.chat.workSession': Record<never, never>;
	'app.templates.chat.reload': Record<never, never>;
	'app.templates.chat.cancelRead': Record<never, never>;
	'app.templates.chat.history': Record<never, never>;
	'app.templates.chat.historyLoading': Record<never, never>;
	'app.templates.chat.cancelHistory': Record<never, never>;
	'app.templates.chat.loadHistory': Record<never, never>;
	'app.templates.chat.retryRead': Record<never, never>;
	'app.templates.chat.noMessages': Record<never, never>;
	'app.templates.chat.selectSession': Record<never, never>;
	'app.templates.chat.messages': Record<never, never>;
	'app.templates.chat.you': Record<never, never>;
	'app.templates.chat.assistant': Record<never, never>;
	'app.templates.chat.toolReadonly': Record<never, never>;
	'app.templates.chat.preparing': Record<never, never>;
	'app.templates.chat.noText': Record<never, never>;
	'app.templates.chat.newContent': Record<never, never>;
	'app.templates.chat.read': Record<never, never>;
	'app.templates.chat.responding': Record<never, never>;
	'app.templates.chat.completed': Record<never, never>;
	'app.templates.chat.stopped': Record<never, never>;
	'app.templates.chat.incomplete': Record<never, never>;
	'app.templates.chat.toolPending': Record<never, never>;
	'app.templates.chat.toolRunning': Record<never, never>;
	'app.templates.chat.toolProcessing': Record<never, never>;
	'app.templates.chat.toolCompleted': Record<never, never>;
	'app.templates.chat.toolError': Record<never, never>;
	'app.templates.chat.minimalWordmark': Record<never, never>;
