					}
				}
				context.emit({
					type: 'tool-state',
					attemptId: request.attemptId,
					sequence: ++sequence,
					tool: {
						id: 'organize',
						name: '本地记录整理',
						state: 'completed',
						text: chatDemoConfig.toolText
					}
				});
				if (selected !== 'eof')
					context.emit({
						type: 'complete',
						attemptId: request.attemptId,
						sequence: ++sequence
